-- CA_0151_la_trustee_area_boards_batch5.sql
-- LA-County TRUSTEE-AREA unified school boards, batch 5: Alhambra, Azusa, Charter Oak, Bellflower.
-- Same pattern as CA_0144 / 0146 / 0149 / 0150 (X0002 polygons from the LA RR/CC precinct layer, DST_USD
-- codes 52 Alhambra, 5 Azusa, 20 Charter Oak, 2 Bellflower; offices off the whole-district row; stale
-- holders closed; current members seated from each district's board page and minutes; Nov 3 2026 races).
--
-- BATCH-SPECIFIC:
--   * Alhambra: the DB held 4 offices for 5 areas -> 1 cloned. Robert Gin (TA 4) was already the DB
--     holder and IS a current member: row + open term kept, office pinned to TA 4. Kenneth Tang's office
--     is pinned to TA 2 and his term closed on his real resignation date (step 4b); Nora Corona
--     Hernandez was appointed 2025-09-09 and is the incumbent in the TA 2 special election.
--   * Alhambra's board is elected across its whole K-12 + 9-12 territory: the RR/CC trustee areas equal
--     TIGER's unified polygon (0600153, 30.4 km2) PLUS its 9-12-only polygon (0606037 G5410, 12.1 km2) to
--     within 0.2 km2, so the coverage gate compares against that union. Addresses in the 9-12-only area
--     (parts of Rosemead/San Gabriel) now correctly see their Alhambra board member.
--   * Azusa TA 1: Adrian Greer was appointed to the full 2022-2026 term after a failure to elect.
--   * Charter Oak: office dd55b530 has no term row (the parallel roster session's CA_0143 deleted a
--     wrong-seat term there); it simply receives a member.
--   * Bellflower: 2 precincts (0.125 km2) carry DIV_USD 0 (no trustee area) in the RR/CC file; they are
--     left out. Members elected at large in 2022 sit on the area the district's governance page lists.
--   * Reuses NetFile rows: Marcia Wilson, Kaysa Moreno (Alhambra), Kristin McGuire, Jeanette Flores
--     (Charter Oak), Mayra Garza (Bellflower).
BEGIN;

CREATE TEMP TABLE _seat (parent_geo text, geo_id text, label text, ta text, ord int, full_name text, first_name text,
                         last_name text, url text, existing_pid uuid, term_start date, prec text, how text, src text,
                         pin_office uuid, vacant_since date, fresh boolean, pid uuid) ON COMMIT DROP;
CREATE TEMP TABLE _hold (parent_geo text, ord int, full_name text, first_name text, last_name text, url text,
                         existing_pid uuid, term_start date, prec text, how text, src text, pid uuid) ON COMMIT DROP;
INSERT INTO _hold (parent_geo, ord, full_name, first_name, last_name, url, existing_pid, term_start, prec, how, src) VALUES
    (NULL, NULL, NULL, NULL, NULL, NULL, NULL::uuid, NULL, NULL, NULL, NULL);
DELETE FROM _hold;
